"""
make_report_facts.py - writes docs/REPORT_FACTS.md from experiments/**/metrics.json, so every number used in the
documents has one source. Re-run after any experiment re-run.

    python scripts/make_report_facts.py
"""

from __future__ import annotations

import json
import re
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
EXP = ROOT / "experiments"
SHOTS = ROOT / "docs" / "screenshots"
DIAG = ROOT / "docs" / "diagrams"
FIGS = ROOT / "docs" / "figures"


def J(name):
    return json.loads((EXP / name / "metrics.json").read_text(encoding="utf-8"))


def row(*cells):
    return "| " + " | ".join(str(c) for c in cells) + " |"


def tbl(header, rows):
    return "\n".join([row(*header), row(*["---"] * len(header))] + [row(*r) for r in rows])


def main() -> None:
    ds, fc, rec = J("dataset"), J("forecasting"), J("recursive")
    dom, ex, inv, cold = J("domain_adaptation"), J("explainability"), J("inventory"), J("cold_start")
    api = J("api_timing") if (EXP / "api_timing").exists() else None
    L: list[str] = []
    a = L.append

    a("# REPORT_FACTS - TrendCast (CSE-A-A17)\n")
    a("Single source of numbers for every submission document. Generated by `scripts/make_report_facts.py` from "
      "`experiments/**/metrics.json`; do not edit by hand.\n")

    a("## 1. Identity\n")
    a("- Product: **TrendCast** - Fashion Demand Forecasting Using Machine Learning And Domain Adaptation (CSE-A, Batch A17, domain AI & ML).")
    a("- Students: B Shilpa (23K91A0547), B Hari Narayana (23K91A0544), A Rani Thejaswini (23K91A0516), A Sanjana (23K91A0511). Guide: Deepthi.")
    a("- Base paper: *Explainable Retail Demand Forecasting: A Hybrid LightGBM-SHAP Framework for Inventory Optimization*, IEEE Access, 2026, DOI 10.1109/access.2026.3675540 (PDF in `Documentary/`).")
    a("- Ports: backend 8317, frontend 5317. No login in this product. Optional Gemini AI Insights (`gemini-flash-latest`) from `.env`.\n")

    a("## 2. Dataset (real)\n")
    a("- Source: **H&M Personalized Fashion Recommendations** (Kaggle competition data: 31,788,324 transactions, 105,542 articles, 1,371,980 customers, per the mirror's dataset card). "
      "Obtained from the parquet mirror `dinhlnd1610/HM-Personalized-Fashion-Recommendations` on Hugging Face; used under the competition's academic / non-commercial terms; **not redistributed** in this repository (`data/real_hm` is git-ignored).")
    a("- Subset used for every measurement (`scripts/make_real_subset.py`): first transaction shard (`transactions/train-00000-of-00007.parquet`: 4,541,190 rows, 2018-09-20 to 2019-01-04, 42,415 articles sold) "
      "-> the **300 best-selling articles** with all their transactions.")
    a(f"- Subset size: **{ds['raw_rows']:,}** transaction rows read; **{ds['clean_rows']:,}** after cleaning (**{ds['raw_rows'] - ds['clean_rows']:,}** exact-duplicate rows dropped = "
      f"{(ds['raw_rows'] - ds['clean_rows']) / ds['raw_rows'] * 100:.1f} %; in H&M a repeated identical row is usually a legitimate repeat purchase, so cleaning understates demand); "
      f"{ds['articles']} articles; {ds['customers']:,} customers; {ds['date_min']} to {ds['date_max']} (107 days).")
    a(f"- Channels (cleaned rows): channel 1 = {ds['channel_rows_raw']['1']:,}, channel 2 = {ds['channel_rows_raw']['2']:,}.")
    a(f"- Modelling table: {ds['daily_rows']:,} article-days (units sold per article per day) -> {ds['feature_rows']:,} rows after zero-filling gaps "
      f"({ds['zero_demand_share_pct']:.2f} % zero-demand rows) x {ds['feature_cols']} model input columns. Mean demand 19.46 units / article-day, median 14, max 566.")
    a(f"- Chronological 80/20 split: train {fc['split']['train_rows']} rows ({fc['split']['train_start'][:10]} to {fc['split']['train_end'][:10]}), "
      f"test {fc['split']['test_rows']} rows ({fc['split']['test_start'][:10]} to {fc['split']['test_end'][:10]}). "
      "The test window contains the Christmas peak and the January sales; the training window contains no earlier year, so yearly seasonality cannot be learned.")
    a("- A **synthetic** H&M-schema sample (`data/sample_hm`, `scripts/make_sample_data.py`: 90 articles, 4,000 customers, 70,974 rows) ships for smoke tests only; no reported metric uses it.\n")

    a("## 3. Environment\n")
    a("- Measured on: Intel Core i5-12500 (6 cores / 12 threads), 15.7 GB RAM, Windows 11 Pro, no GPU, other jobs running on the same machine.")
    a("- Software: Python 3.11.9, scikit-learn 1.5.0, XGBoost 2.0.3, LightGBM 4.7.0, pandas 2.2.1, NumPy 1.26.4, FastAPI 0.143.3, Streamlit 1.66.0 (original UI), React 19 + Vite 8 + Recharts (web UI), Playwright (screenshots). LightGBM was installed for the baseline only (it is not in the shipped venv).\n")

    a("## 4. Architecture summary\n")
    a("- `src/` pure-Python pipeline (data_loader, preprocessing, demand_forecasting, feature_engineering, baseline_models, xgboost_model, domain_adaptation, evaluation, visualization, gemini_helper); `app.py` Streamlit UI (11 pages, original); "
      "`backend/` FastAPI layer (main.py 626 lines, state.py, gemini_api.py) over `src/`, in-memory single-user pipeline state; `frontend/` React UI (13 pages: landing, overview, upload, explore, demand, features, training, domain, evaluation, forecast, insights, about, 404).")
    a("- No database: pipeline state is a process-wide dict `S` guarded by an RLock; trained models are saved to `models/baseline_xgboost.joblib`, `adapted_xgboost.joblib`, `feature_info.joblib`.")
    a("- Pipeline: upload CSVs -> validate columns -> clean (parse dates, drop null ids, price<=0, exact duplicates) -> left-join articles (+customers) -> aggregate daily demand per article (rows = units) -> fill missing days with 0 -> features -> chronological split -> moving average / XGBoost (optional RandomizedSearchCV with TimeSeriesSplit) -> domain adaptation (logistic domain classifier, weight = p/(1-p) clipped at 20, weighted XGBoost) -> evaluation -> recursive 7/14/30-day forecast -> optional Gemini explanation.")
    a("- Features (31 model inputs): price, sales_channel_id, 6 label-encoded attributes (product_type, product_group, colour_group, department, section, garment_group), 14 calendar (year, month, day, day_of_week, week_of_year, day_of_year, quarter, is_weekend, is_month_start, is_month_end, month sin/cos, day-of-week sin/cos), 9 lag/rolling (lag 1/7/14/28, rolling mean 7/14/28, rolling std 7/28; shifted so the current day is excluded).")
    a("- XGBoost defaults: n_estimators 300, max_depth 8, learning_rate 0.05, subsample 0.8, colsample_bytree 0.8, squared error, random_state 42. Tuning: RandomizedSearchCV 10 iterations x 3 TimeSeriesSplit folds over n_estimators, max_depth, learning_rate, subsample, colsample_bytree, min_child_weight.")
    a("- Metrics: RMSE, MAE, safe MAPE (zero-actual rows excluded, count reported), R2; WAPE added offline.\n")

    a("## 5. Endpoints (22, all under /api)\n")
    a("GET health, state, data/report, explore, demand/table, features, training/split, training/results, domain/options, domain/last, evaluation, forecast/articles, ai/status; "
      "POST data/upload, features/build, training/baseline, training/xgboost, training/load, domain/run, forecast, ai/explain, ai/forecast-summary. "
      "Gating: downstream routes return 409 with a plain-language message until upstream steps are done; validation errors return 400; training fraction validated 0.5-0.95 (422); horizon must be 7, 14 or 30 (400).\n")

    a("## 6. Forecasting results (chronological 80/20, real H&M subset)\n")
    mrows = []
    for k, v in fc["models"].items():
        mrows.append([k, f"{v['RMSE']:.3f}", f"{v['MAE']:.3f}", f"{v['MAPE (%)']:.1f}", f"{v['R2']:.3f}", f"{v['WAPE (%)']:.1f}"])
    a(tbl(["Model", "RMSE", "MAE", "MAPE % (non-zero rows)", "R2", "WAPE %"], mrows))
    s = fc["xgboost_seed_stats"]
    a(f"\n- XGBoost default over 5 seeds: RMSE {s['RMSE']['mean']:.3f} +/- {s['RMSE']['std']:.3f}, MAE {s['MAE']['mean']:.3f} +/- {s['MAE']['std']:.3f}, R2 {s['R2']['mean']:.3f} +/- {s['R2']['std']:.3f}. "
      f"Fit time {fc['xgboost_fit_seconds_mean']:.2f} s; prediction {fc['xgboost_prediction_us_per_row']:.1f} microseconds per row; tuning {fc['tuning_seconds']:.1f} s; RF fit {fc['models']['Random forest']['fit_seconds']:.1f} s.")
    a(f"- Tuned parameters: {fc['tuned_best_params']}.")
    a(f"- MAPE is huge because it is computed on low-volume days; 345 zero-demand test rows are excluded from MAPE.")
    a(f"- Daily-total WAPE over the test window: XGBoost {fc['test_daily_totals_error']['xgb_daily_wape_pct']:.1f} %, moving average {fc['test_daily_totals_error']['ma_daily_wape_pct']:.1f} %.")
    a("- **Finding:** the project's XGBoost beats the app's moving-average baseline but **does not beat the one-line 'repeat yesterday' (lag 1) forecast or the shifted 7-day rolling mean** on this window; LightGBM and the tuned model are closer but still behind lag 1.\n")
    a("### Feature-group ablation (XGBoost default, mean of 3 seeds)\n")
    a(tbl(["Feature set", "inputs", "RMSE", "WAPE %", "R2"], [[k, v["n_features"], f"{v['RMSE']:.3f}", f"{v['WAPE (%)']:.1f}", f"{v['R2']:.3f}"] for k, v in fc["ablation"].items()]))
    a("\n- **Finding:** lag/rolling features carry the model; removing them collapses R2 to negative. Calendar-only is worse than predicting the mean of the test window. The shipped all-feature model is *worse* than the lag/rolling-only model: the absolute-time features (year, quarter, day_of_year, is_month_end) cannot extrapolate to dates beyond the training range.\n")
    a("### Rolling-origin backtest (train up to the origin, test the next ~14 days; XGBoost seed 42)\n")
    a(tbl(["Train until", "Test until", "Test rows", "XGBoost RMSE", "Moving avg RMSE", "Naive lag-1 RMSE", "Seasonal naive RMSE"],
          [[b["train_until"], b["test_until"], b["test_rows"], f"{b['xgboost']['RMSE']:.2f}", f"{b['moving_average']['RMSE']:.2f}", f"{b['naive_lag1']['RMSE']:.2f}", f"{b['seasonal_naive']['RMSE']:.2f}"] for b in fc["rolling_origin"]]))
    a("\n- XGBoost beats the moving average in all three folds; it beats naive lag-1 in the first fold only (27.65 vs 30.10 RMSE).\n")
    a("### Gain importance (shipped XGBoost, seed 42, top 8)\n")
    a(", ".join(f"{d['feature']} {d['importance']:.3f}" for d in fc["gain_importance_top15"][:8]) + ".\n")

    a("## 7. Recursive multi-day forecast (the app's 7/14/30-day feature), origin " + rec["origin"] + "\n")
    a(f"{rec['articles_scored']} articles scored over the next up-to-30 days (model trained on dates before the origin; the loop in `backend/main.py::forecast` replicated in `scripts/run_experiments.py`).\n")
    rr = []
    for name, lab in (("xgb_app", "XGBoost recursive (as shipped)"), ("xgb_fixed", "XGBoost recursive, calendar features refreshed"), ("flat_ma7", "Flat mean of last 7 days"), ("repeat_last_week", "Repeat last week's pattern")):
        v = rec["results"][name]
        rr.append([lab] + [f"{v[k]['RMSE']:.2f} / {v[k]['WAPE (%)']:.1f}" for k in ("days 1-7", "days 1-14", "days 1-30")] + [f"{b['WAPE (%)']:.0f}" for b in v["by_band"]])
    a(tbl(["Method", "Days 1-7 RMSE / WAPE %", "Days 1-14", "Days 1-30", "WAPE % d1-7", "d8-14", "d15-30"], rr))
    a("\n- **Finding:** the recursive forecast is *worse than a flat 7-day mean at every horizon* and degrades quickly (WAPE 41 -> 77 -> 124 % by band). The app's loop also leaves week_of_year, day_of_year, quarter, is_month_start / is_month_end frozen at the last observed day; refreshing them did not help (it was worse at 30 days). Price and channel are held at their last values.\n")

    a("## 8. Domain adaptation (importance weighting, the app's procedure, 5 XGBoost seeds)\n")
    a("Protocol (`backend/main.py::run_domain`): source model trained on all source-domain rows; target test = later 50 % of target dates; domain classifier = logistic regression (max_iter 1000, unscaled features, domain column excluded); weight = p/(1-p) clipped at 20; weighted XGBoost. "
      "Extra controls added offline: target-only oracle (first half of target), pooled source + target-train unweighted, shuffled weights, weights rescaled to mean 1, and a time-clean protocol (source restricted to dates before the target test window).\n")
    dr = []
    for p in dom["pairs"]:
        e, d = p["app"], p["diagnostics"]
        dr.append([p["label"], f"{d['clf_accuracy'] * 100:.1f}", d["source_rows"], d["target_test_rows"], f"{e['before']['RMSE']['mean']:.2f}", f"{e['adapted']['RMSE']['mean']:.2f}",
                   f"{e['rmse_improvement_pct_mean']:+.1f}", f"{e['adapted_beats_before_in_seeds']}/5", f"{e['shuffled_improvement_pct_mean']:+.1f}", f"{e['target_only_oracle']['RMSE']['mean']:.2f}",
                   f"{e['pooled_unweighted']['RMSE']['mean']:.2f}", f"{e['normalised_improvement_pct_mean']:+.1f}", f"{p['time_clean']['rmse_improvement_pct_mean']:+.1f}"])
    a(tbl(["Pair (source -> target)", "Domain clf acc %", "Source rows", "Target test rows", "RMSE before", "RMSE adapted", "Improvement %", "Seeds improved", "Shuffled-weights impr. %", "Target-only RMSE", "Pooled RMSE", "Mean-1 weights impr. %", "Time-clean impr. %"], dr))
    sm = dom["summary"]
    a(f"\n- Adaptation as shipped improved RMSE on **{sm['pairs_where_adaptation_helped']} of {sm['pairs_total']}** pairs (range {sm['min']:+.1f} % to {sm['max']:+.1f} %, mean {sm['mean_rmse_improvement_pct']:+.1f} %). "
      f"With weights rescaled to mean 1 the mean is {sm['normalised_mean_rmse_improvement_pct']:+.1f} %; under the time-clean protocol {sm['time_clean_mean_rmse_improvement_pct']:+.1f} % (mean-1 weights + time-clean: {sm['normalised_time_clean_mean_rmse_improvement_pct']:+.1f} %).")
    a("- **Finding 1:** the only clear gain (online -> store, +12 %) disappears (-2.8 %) when the source model is not allowed to train on dates inside the target test window - it came from time overlap, not from adaptation. Shuffled weights give +2.5 % on that pair, so part of the effect is noise.")
    a("- **Finding 2:** when the domain classifier separates the domains perfectly (department pairs, accuracy 100 %), p/(1-p) is ~1e-6..1e-3 for every source row (mean weight 5e-5 and 4e-4); XGBoost's `min_child_weight=1` can then never be met, the model stops splitting and predicts a constant (R2 about 0, RMSE +46 % worse). Rescaling the same weights to mean 1 removes the collapse (Knitwear -> Trouser +1.9 %).")
    a("- **Finding 3:** simply pooling source rows with the first half of the target domain, without weights, beats weighted adaptation on 5 of 6 pairs (the exception is online -> store, 9.78 vs 9.50); the target-only model is worse than the source-only model on 5 of 6 pairs (half of a small target domain is too little data).")
    a("- Logistic regression does not converge in 1000 iterations on the unscaled features (sklearn ConvergenceWarning on every run).")
    a("- App screenshot run (default Channel 1 -> Channel 2, seed 42): RMSE 18.983 -> 18.989 (-0.0 % worse), domain classifier accuracy 66.3 %.\n")

    a("## 9. Explainability (offline TreeSHAP; the web app shows gain importance only)\n")
    a(tbl(["Feature", "mean |SHAP| (units)", "gain importance"], [[t["feature"], f"{t['mean_abs_shap']:.2f}", f"{t['gain_importance']:.3f}"] for t in ex["top10_by_shap"]]))
    a(f"\n- Spearman rank correlation between mean |SHAP| and gain importance: {ex['spearman_rank_corr_shap_vs_gain']:.2f}. Top 3 by SHAP carry {ex['top3_share_of_total_abs_shap_pct']:.0f} % of total attribution (lag_1 alone dominates). Top 3 by gain: {', '.join(ex['top3_by_gain'])} - gain overstates calendar features that split often but contribute little.")
    a(f"- SHAP additivity check (sum of contributions equals the prediction): max abs error {ex['shap_additivity_max_abs_error']:.1e} on {ex['n_test_rows']} rows.\n")

    a("## 10. Inventory impact (test window, 80,699 units actually sold)\n")
    ir = []
    for k in ("XGBoost", "Moving average (7d)", "Seasonal naive (lag 7)"):
        v = inv[k]
        ir.append([k, f"{v['predicted_units']:,.0f}", f"{v['bias_pct']:+.1f}", f"{v['understock_units']:,.0f} ({v['understock_pct_of_demand']:.1f} %)", f"{v['overstock_units']:,.0f} ({v['overstock_pct_of_demand']:.1f} %)", f"{v['wape_pct']:.1f}"])
    a(tbl(["Forecast", "Predicted units", "Bias %", "Under-forecast units (shortfall)", "Over-forecast units (excess)", "WAPE %"], ir))
    a("\n- Not part of the shipped app: computed offline from the test predictions. XGBoost over-forecasts the window by 23.6 % in total but loses fewer sales (16.4 %) than the moving average (29.4 %). Safety-stock sizing was not evaluated out-of-sample.\n")

    a("## 11. Cold start (unseen articles, 5-fold GroupKFold by article)\n")
    cr = []
    for k, lab in (("attributes_calendar_only_unseen_article", "XGBoost, attributes + calendar + price (no lags)"), ("product_type_mean_baseline_unseen_article", "Mean demand of the product type"), ("full_features_unseen_article_lags_assumed_known", "Reference: full features incl. the article's own lags")):
        v = cold[k]
        cr.append([lab, f"{v['RMSE']:.2f}", f"{v['MAE']:.2f}", f"{v['R2']:.3f}", f"{v['WAPE (%)']:.1f}"])
    a(tbl(["Model", "RMSE", "MAE", "R2", "WAPE %"], cr))
    a("\n- The shipped app has **no cold-start mode**: its forecast needs >= 5 days of history and lag features. The offline test shows attribute-only prediction for unseen articles is better than the product-type mean (R2 0.27 vs -0.01) but far worse than having history (R2 0.68). Objective 'new products' is therefore only partly addressed and was not implemented in the product.\n")

    a("## 12. Performance (API, 127.0.0.1, real subset)\n")
    if api:
        a(tbl(["Stage", "Seconds"], [[k, v] for k, v in api["stages_seconds"].items()]))
        a("")
        a(tbl(["Endpoint", "n", "median ms", "p95 ms"], [[k, v["n"], v["median"], v["p95"]] for k, v in api["latency_ms"].items()]))
        a("")
    a("\n## 13. Testing\n")
    a("- `tests/test_pipeline.py` (22 unit tests) + `tests/test_api.py` (17 API tests through FastAPI TestClient on synthetic data) = **39 pytest tests, all pass** (run `python -m pytest tests -q`).")
    a("- `scripts/smoke_test.py`: 26 end-to-end checks against a live backend on the synthetic sample, all pass (the AI check passes by returning a clear 502 error when Gemini is unreachable).")
    a("- Browser: `scripts/capture_screens.py` drives the real UI with the real subset; one run produced 25 screenshots and reported 3 console/network problems, all from the Gemini call (502 Bad Gateway on /api/ai/explain). No other console error, page error or failed request.")
    a("- Not tested: concurrent users (single shared state by design), full-size H&M (31.8 M rows), accessibility audit, load testing, browsers other than Chrome.\n")

    a("## 14. Known defects / honest limitations found (product code untouched in this documentation run)\n")
    for t in [
        "Cleaning drops exact duplicate rows (11.6 % of the subset) although repeated identical H&M rows are real repeat purchases: demand is understated.",
        "`sales_channel_id` and `price` of the *target day* are model inputs (daily mode / mean of that day's transactions) - they are known planned inputs at best and partly leak same-day information; in recursive forecasts they are frozen at the last value.",
        "The domain label is the day's most frequent channel, but demand counts both channels, so 'channel domains' are mixtures.",
        "Source model for domain adaptation trains on dates that overlap the target test window (see time-clean result).",
        "Instance weights are not normalised; perfectly separable domains give weights ~1e-5 and XGBoost collapses to a constant.",
        "Domain classifier uses unscaled features; logistic regression does not converge (1000 iterations).",
        "Recursive forecast freezes week_of_year, day_of_year, quarter, month_start/end; error grows from WAPE 41 % (days 1-7) to 124 % (days 15-30).",
        "Absolute-time features (year, quarter, day_of_year) cannot extrapolate beyond the training dates; a lag/rolling-only model is better on the held-out window.",
        "Feature importance shown in the app is gain-based (not SHAP as in the base paper); inventory impact is not computed in the app; no cold-start mode.",
        "`src/baseline_models.train_lightgbm` passes pandas objects; with LightGBM 4.7 on this machine it crashed (access violation) unless lightgbm is imported before pandas/xgboost.",
        "Only 107 days, 300 best-selling articles and 2 sales channels: no multi-year seasonality, no new-store domain, no promotion data (H&M has none).",
        "Gemini AI Insights depends on an external service: during this run it returned 503 (high demand) and timed out, so the screen shows the error state in several captures.",
    ]:
        a(f"- {t}")
    a("")

    a("## 15. Screenshot inventory (`docs/screenshots`, 1440x900, real subset loaded)\n")
    a("\n".join(f"- `{p.name}`" for p in sorted(SHOTS.glob("*.png"))) if SHOTS.exists() else "- none")
    a("\nThe Evaluation, importance and comparison screens show the tuned XGBoost (last model trained in the capture run: RMSE 10.341, R2 0.421); the default model scores RMSE 11.065 / 11.089 over 5 seeds.\n")
    if DIAG.exists():
        a("## 16. Diagrams (`docs/diagrams`)\n")
        a("\n".join(f"- `{p.name}`" for p in sorted(DIAG.glob("*.png"))) + "\n")
    if FIGS.exists():
        a("## 17. Result figures (`docs/figures`)\n")
        a("\n".join(f"- `{p.name}`" for p in sorted(FIGS.glob("*.png"))) + "\n")
    out = ROOT / "docs" / "REPORT_FACTS.md"
    out.write_text("\n".join(L) + "\n", encoding="utf-8")
    print("wrote", out, len("\n".join(L).split()), "words")


if __name__ == "__main__":
    main()
